var BANNER = ["wechat", "x"];
var items = (points, subtitle, max) => {
  const xs2 = (points?.length ? points : subtitle.split(/[\n,，、；;|｜]/)).map((s3) => s3.trim()).filter(Boolean);
  return xs2.length >= 2 ? xs2.slice(0, max) : [];
};
var mark = (o3, kind = "mark") => Object.assign(o3, { qcKind: kind });
function arrow2(x0, y0, x1, y1, bend, color, weight) {
  const mx = (x0 + x1) / 2 + bend, my = (y0 + y1) / 2 - bend * 0.4;
  const ang = Math.atan2(y1 - my, x1 - mx);
  const head = weight * 3.4;
  const a3 = (k3) => `${(x1 - Math.cos(ang + k3) * head).toFixed(1)} ${(y1 - Math.sin(ang + k3) * head).toFixed(1)}`;
  return mark(new Mo(`M${x0} ${y0} Q${mx} ${my} ${x1} ${y1} M${a3(0.55)} L${x1} ${y1} L${a3(-0.55)}`, { fill: "", stroke: color, strokeWidth: weight, strokeLineCap: "round", strokeLineJoin: "round", objectCaching: false }));
}
function brushBlock(x3, y3, w3, h3, color, seed = 3) {
  const n3 = 9;
  let s3 = seed * 7919 + 17;
  const rnd = () => {
    s3 = (s3 * 9301 + 49297) % 233280;
    return s3 / 233280;
  };
  let d3 = `M${x3} ${y3 + h3 * 0.12}`;
  for (let k3 = 1; k3 <= n3; k3++) d3 += ` L${(x3 + w3 * k3 / n3).toFixed(1)} ${(y3 + h3 * (0.04 + rnd() * 0.16)).toFixed(1)}`;
  d3 += ` L${(x3 + w3 + h3 * 0.12).toFixed(1)} ${(y3 + h3 * 0.55).toFixed(1)}`;
  for (let k3 = n3; k3 >= 0; k3--) d3 += ` L${(x3 + w3 * k3 / n3).toFixed(1)} ${(y3 + h3 * (0.84 + rnd() * 0.14)).toFixed(1)}`;
  return mark(new Mo(`${d3} Z`, { fill: color, stroke: "", angle: -1.2 }), "mark-title");
}
