      const parts = i3.subtitle.split(/\s*[|｜]\s*|\s+vs\.?\s+/i).map((x3) => x3.trim()).filter(Boolean);
      const [A3, B2] = parts.length >= 2 ? [parts[0], parts[1]] : [i3.zh ? "\u4E4B\u524D" : "Before", i3.zh ? "\u4E4B\u540E" : "After"];
