// src/original/fontcheck.ts
var CJK = /[㐀-鿿]/;
function scriptOf(f5) {
  if (f5.cjk === true) return "cjk";
  if (f5.cjk === false) return "latin";
  const lib = FONT_LIBRARY.find((x3) => x3.family === f5.family);
  if (lib) return lib.mood === "latin" ? "latin" : "cjk";
  if (f5.zh && CJK.test(f5.zh)) return "cjk";
  return "unknown";
}
function fontProblem(family, text2, book, zh4) {
  const f5 = book.find((x3) => x3.family.toLowerCase() === family.trim().toLowerCase());
  if (!f5) return zh4 ? `\u6CA1\u6709\u300C${family}\u300D\u8FD9\u6B3E\u5B57\u4F53\uFF1B\u53EA\u80FD\u7528\u5B57\u4F53\u6E05\u5355\u91CC\u7684` : `There is no font "${family}"; use one from the font list`;
  if (CJK.test(text2) && scriptOf(f5) === "latin") return zh4 ? `\u300C${family}\u300D\u53EA\u6709\u82F1\u6587\u5B57\u5F62\uFF0C\u300C${text2.replace(/\s+/g, "").slice(0, 12)}\u300D\u91CC\u7684\u4E2D\u6587\u4F1A\u53D8\u6210\u7CFB\u7EDF\u9ED8\u8BA4\u5B57\uFF1B\u4E2D\u6587\u8BF7\u9009\u4E2D\u6587\u5B57\u4F53` : `"${family}" has no Chinese glyphs; pick a Chinese font for this text`;
  return void 0;
}

