// src/original/settingsui.ts
var Row = class {
  el;
  control;
  nameEl;
  descEl;
  constructor(parent, name = "", desc = "") {
    this.el = parent.createDiv("qcs-row");
    const info = this.el.createDiv("qcs-info");
    this.nameEl = info.createDiv({ cls: "qcs-name" });
    this.descEl = info.createDiv({ cls: "qcs-desc" });
    this.control = this.el.createDiv("qcs-control");
    this.setName(name);
    this.setDesc(desc);
  }
  setName(name) {
    this.nameEl.setText(name);
    this.nameEl.toggleClass("is-empty", !name);
    return this;
  }
  setDesc(desc) {
    this.descEl.setText(desc);
    this.descEl.toggleClass("is-empty", !desc);
    return this;
  }
  /** Wide control rows put the input under the text instead of beside it (long URLs, textareas). */
  stack() {
    this.el.addClass("is-stacked");
    return this;
  }
  addText(cb) {
    cb(new TextComponent(this.control));
    return this;
  }
  addDropdown(cb) {
    cb(new DropdownComponent(this.control));
    return this;
  }
  addToggle(cb) {
    cb(new ToggleComponent(this.control));
    return this;
  }
  addSlider(cb) {
    cb(new SliderComponent(this.control));
    return this;
  }
  addButton(cb) {
    cb(new ButtonComponent(this.control));
    return this;
  }
};
function section(parent, title, desc, step) {
  const box = parent.createDiv("qcs-section");
  const head = box.createDiv("qcs-section-head");
  if (step !== void 0) head.createSpan({ text: String(step), cls: "qcs-step" });
  const text2 = head.createDiv("qcs-section-text");
  text2.createDiv({ text: title, cls: "qcs-section-title" });
  if (desc) text2.createDiv({ text: desc, cls: "qcs-section-desc" });
  return box.createDiv("qcs-section-body");
}
function statusBar(parent, tone2, text2, detail) {
  const el = parent.createDiv(`qcs-status is-${tone2}`);
  el.createSpan({ cls: "qcs-dot" });
  const t3 = el.createDiv("qcs-status-text");
  t3.createDiv({ text: text2, cls: "qcs-status-main" });
  if (detail) t3.createDiv({ text: detail, cls: "qcs-status-detail" });
  return { el, action: el.createDiv("qcs-status-action") };
}
function more(parent, label, open = false) {
  const d3 = parent.createEl("details", { cls: "qcs-more" });
  if (open) d3.setAttribute("open", "");
  d3.createEl("summary", { text: label });
  return d3.createDiv("qcs-more-body");
}

